qualification/hcsn_boundary_audit/refrac:
"""Bounded exact-age refractory transport research prototype (not HCSN flow).

Uniform/point HIT-time packets are external inputs. Their release-time law is
shifted by an exact fixed delay and retained without phase-bin reconstruction.
Released packets retain absolute release support for a future active solver;
lumping them at an interval endpoint would change the model. This module does
not solve diffusion, infer hit laws, implement autograd or migrate checkpoints.
"""

from dataclasses import dataclass
from fractions import Fraction


def rational(value):
    """Use explicit rational/int inputs; do not silently rationalize floats."""
    if isinstance(value, bool) or not isinstance(value, (int, Fraction)):
        raise ValueError("expected Fraction or int")
    return Fraction(value)


@dataclass(frozen=True)
class Packet:
    """Uniform law on [start,end], or an atom if start==end.

    mass and marked content are TOTALS on this packet, not densities. Content
    may be signed. Before release these bounds are absolute release times;
    supplied to advance_to as a hit packet they are absolute hit times instead.
    """

    identity: str
    start: Fraction
    end: Fraction
    mass: Fraction
    content: tuple[Fraction, ...]

    def __post_init__(self):
        if not isinstance(self.identity, str) or not self.identity:
            raise ValueError("packet requires a nonempty identity")
        for name in ("start", "end", "mass"):
            object.__setattr__(self, name, rational(getattr(self, name)))
        if self.start < 0 or self.end < self.start or self.mass <= 0:
            raise ValueError("invalid support or nonpositive mass")
        if not isinstance(self.content, tuple) or not 1 <= len(self.content) <= 128:
            raise ValueError("content requires 1..128 fixed channels")
        object.__setattr__(self, "content", tuple(map(rational, self.content)))

    def split_at(self, time):
        """Return released and pending packets, preserving each support law."""
        time = rational(time)
        if time < self.start:
            return None, self
        if time >= self.end:
            return self, None
        ratio = (time - self.start) / (self.end - self.start)
        if ratio == 0:
            return None, self
        released = Packet(self.identity, self.start, time, self.mass * ratio,
                          tuple(x * ratio for x in self.content))
        pending = Packet(self.identity, time, self.end, self.mass * (1 - ratio),
                         tuple(x * (1 - ratio) for x in self.content))
        return released, pending


@dataclass(frozen=True)
class ReleaseReceipt:
    """A new immutable state and releases within the requested interval."""

    state: "RefractoryState"
    released: tuple[Packet, ...]
    incoming_mass: Fraction
    incoming_content: tuple[Fraction, ...]


@dataclass(frozen=True)
class RefractoryState:
    """A finite set of exact support packets; overflow raises before mutation.

    max_packets is a count bound, not a complete memory/bit-complexity bound.
    No merging or lossy compaction silently relaxes it. IDs are scoped to the
    pending packet set, not an owner-authenticated deduplication ledger.
    """

    time: Fraction
    packets: tuple[Packet, ...]
    channels: int
    max_packets: int = 4096
    delay: Fraction = Fraction(1, 5)

    def __post_init__(self):
        object.__setattr__(self, "time", rational(self.time))
        object.__setattr__(self, "delay", rational(self.delay))
        if (self.time < 0 or self.delay < 0 or isinstance(self.channels, bool)
                or not isinstance(self.channels, int) or not 1 <= self.channels <= 128
                or isinstance(self.max_packets, bool)
                or not isinstance(self.max_packets, int) or not 1 <= self.max_packets <= 4096
                or not isinstance(self.packets, tuple)):
            raise ValueError("invalid state geometry or packet budget")
        if len(self.packets) > self.max_packets:
            raise OverflowError("packet budget exceeded; no implicit compaction")
        identities = set()
        for packet in self.packets:
            if not isinstance(packet, Packet) or len(packet.content) != self.channels:
                raise ValueError("invalid packet or content shape")
            if packet.start < self.time or packet.end <= self.time:
                raise ValueError("pending support must have a nonempty future part")
            if packet.identity in identities:
                raise ValueError("duplicate pending identity")
            identities.add(packet.identity)

    def advance_to(self, target, hits=()):
        """Transport exactly, admitting uniform/point hit influx in [time,target].

        The caller must provide the upstream hit law; no hit mass is computed
        here. A point releases at its exact deadline, including the right
        endpoint. Delay is fixed by the immutable state and may be zero.
        New hit laws are supplied once per call;
        replaying them is a new influx, not an idempotent read.
        """
        target = rational(target)
        if target < self.time or not isinstance(hits, tuple):
            raise ValueError("nonmonotone clock or mutable hit list")
        if len(self.packets) + len(hits) > self.max_packets:
            raise OverflowError("transient packet budget exceeded")
        identities = {p.identity for p in self.packets}
        shifted = []
        for hit in hits:
            if (not isinstance(hit, Packet) or len(hit.content) != self.channels
                    or hit.start < self.time or hit.end > target
                    or hit.identity in identities):
                raise ValueError("hit support, content or identity is invalid")
            identities.add(hit.identity)
            shifted.append(Packet(hit.identity, hit.start + self.delay, hit.end + self.delay,
                                  hit.mass, hit.content))
        released, pending = [], []
        for packet in self.packets + tuple(shifted):
            out, rest = packet.split_at(target)
            if out is not None:
                released.append(out)
            if rest is not None:
                pending.append(rest)
        state = RefractoryState(target, tuple(pending), self.channels, self.max_packets, self.delay)
        incoming_mass = sum((p.mass for p in hits), Fraction(0))
        incoming_content = tuple(sum((p.content[j] for p in hits), Fraction(0))
                                 for j in range(self.channels))
        return ReleaseReceipt(state, tuple(released), incoming_mass, incoming_content)

    def project_remaining(self, edges):
        """Read-only phase-bin projection; the returned bins are never state.

        Edges must cover every pending remaining-time support. Exact interval
        overlap handles uniform packets; half-open bins put boundary atoms in
        the right bin, except the final right edge belongs to the final bin.
        """
        edges = tuple(map(rational, edges))
        if (len(edges) < 2 or edges[0] != 0
                or any(b <= a for a, b in zip(edges, edges[1:]))):
            raise ValueError("strict edges must start at zero")
        probability = [Fraction(0) for _ in edges[1:]]
        marked = [[Fraction(0)] * self.channels for _ in edges[1:]]
        for packet in self.packets:
            lo, hi = packet.start - self.time, packet.end - self.time
            if hi > edges[-1]:
                raise ValueError("projection edges do not cover pending support")
            for j, (left, right) in enumerate(zip(edges, edges[1:])):
                if lo == hi:
                    ratio = Fraction(int(left <= lo < right or
                                         j == len(probability) - 1 and lo == right))
                else:
                    ratio = max(Fraction(0), min(hi, right) - max(lo, left)) / (hi - lo)
                probability[j] += packet.mass * ratio
                for k, value in enumerate(packet.content):
                    marked[j][k] += value * ratio
        return tuple(probability), tuple(tuple(row) for row in marked)

qualification/hcsn_boundary_audit/spatia:
"""Research-only killed spatial CTMC; not the HCSN returning-tail/reset model.

State nodes are 0,h,...,L. Both endpoints absorb, with lower-hit and upper-exit
kept distinct. A fixed birth/death generator evolves nodal masses without
reconstructing a uniform density after each observation interval.
"""

from dataclasses import dataclass
import math

import numpy as np
from scipy.linalg import expm, solve_banded


def _real(name, value, *, positive=False):
    if isinstance(value, (bool, np.bool_)) or not isinstance(value, (int, float)):
        raise ValueError(f"{name} must be a finite real")
    if not math.isfinite(value) or (positive and value <= 0):
        raise ValueError(f"invalid {name}")
    return float(value)


@dataclass(frozen=True)
class KilledSpatialGenerator:
    """One immutable constant-physics finite-domain research generator.

    Central rates are accepted only when both are nonnegative. No clipping,
    normalization or drift-dependent change of scheme is performed.
    """

    intervals: int
    endpoint: float
    mu: float
    sigma: float

    def __post_init__(self):
        if type(self.intervals) is not int or not 4 <= self.intervals <= 512:
            raise ValueError("intervals must be an integer in [4,512]")
        for name in ("endpoint", "mu", "sigma"):
            _real(name, getattr(self, name), positive=name != "mu")
        if (
            not 0.001 <= self.endpoint <= 8
            or not abs(self.mu) <= 2
            or not 0.05 <= self.sigma <= 2
        ):
            raise ValueError(
                "research domain requires L in [.001,8], |mu|<=2, sigma in [.05,2]"
            )
        if not all(math.isfinite(x) and x >= 0 for x in self.rates):
            raise ValueError("nonfinite or negative jump rate: refine the spatial grid")

    @property
    def spacing(self):
        return self.endpoint / self.intervals

    @property
    def rates(self):
        h = self.spacing
        diffusion = (self.sigma / h) ** 2 / 2
        advection = self.mu / (2 * h)
        return diffusion - advection, diffusion + advection

    def matrix(self):
        n, (down, up) = self.intervals, self.rates
        result = np.zeros((n + 1, n + 1), dtype=np.float64)
        indices = np.arange(1, n)
        result[indices, indices - 1] = down
        result[indices, indices + 1] = up
        result[indices, indices] = -(down + up)
        return result

    def transition(self, duration):
        duration = _real("duration", duration)
        if not 0 <= duration <= 2:
            raise ValueError("research duration must be in [0,2]")
        # expm on the full generator retains the two separate absorbing states.
        result = expm(duration * self.matrix())
        if not np.all(np.isfinite(result)):
            raise ArithmeticError("unresolved transition exponential")
        return result

    def _solve(self, discount, rhs):
        n, (down, up) = self.intervals, self.rates
        band = np.zeros((3, n - 1), dtype=np.float64)
        band[0, 1:] = -up
        band[1] = discount + down + up
        band[2, :-1] = -down
        return solve_banded((1, 1), band, rhs)

    def discounted_lower_hit(self, discount):
        """E[exp(-q*tau0); tau0<tauL] at all nodes, including endpoints."""
        discount = _real("discount", discount, positive=True)
        if not 0.001 <= discount <= 4:
            raise ValueError("research discount must be in [.001,4]")
        rhs = np.zeros(self.intervals - 1)
        rhs[0] = self.rates[0]
        values = np.concatenate(([1.0], self._solve(discount, rhs), [0.0]))
        if not np.all(np.isfinite(values)) or np.min(values) < 0 or np.max(values) > 1:
            raise ArithmeticError("unresolved discounted-hit solve")
        return values

    def lower_hit_partials(self, discount):
        """Implicit derivatives of this discrete solve, not continuum/AD evidence."""
        discount = _real("discount", discount, positive=True)
        if min(self.rates) <= 0:
            raise ValueError(
                "two-sided physical partials require strictly positive rates"
            )
        values = self.discounted_lower_hit(discount)
        h = self.spacing
        rhs_mu = (values[2:] - values[:-2]) / (2 * h)
        rhs_sigma = self.sigma * (values[:-2] - 2 * values[1:-1] + values[2:]) / h**2
        return {
            name: np.concatenate(([0.0], self._solve(discount, rhs), [0.0]))
            for name, rhs in (
                ("mu", rhs_mu),
                ("sigma", rhs_sigma),
                ("discount", -values[1:-1]),
            )
        }


def continuum_lower_hit(nodes, endpoint, mu, sigma, discount):
    """Closed-form finite-interval BVP: L phi=q phi, phi(0)=1, phi(L)=0.

    This reference has a real upper killing boundary, not a returning tail.
    Stable exponential differences avoid sinh overflow.
    """
    endpoint = _real("endpoint", endpoint, positive=True)
    mu = _real("mu", mu)
    sigma = _real("sigma", sigma, positive=True)
    discount = _real("discount", discount, positive=True)
    if not 0.001 <= endpoint <= 8 or not abs(mu) <= 2 or not 0.05 <= sigma <= 2:
        raise ValueError("reference is outside the declared research physics domain")
    if not 0.001 <= discount <= 4:
        raise ValueError("research discount must be in [.001,4]")
    x = np.asarray(nodes, dtype=np.float64)
    if not np.all(np.isfinite(x)) or np.any(x < 0) or np.any(x > endpoint):
        raise ValueError("nodes must lie in the finite interval")
    kappa = math.hypot(mu, math.sqrt(2 * discount) * sigma)
    beta = kappa / sigma**2
    # Stable positive half-line Laplace exponent, including negative drift.
    alpha = (mu + kappa) / sigma**2 if mu >= 0 else 2 * discount / (kappa - mu)
    return (
        np.exp(-alpha * x)
        * -np.expm1(-2 * beta * (endpoint - x))
        / -math.expm1(-2 * beta * endpoint)
    )

qualification/hcsn_joint_dde/torch_physi:
"""CPU/FP64 first-order physical VJP for the fixed-prior variational DDE.

The SciPy forward and explicit variational Jacobian are evaluated anew for
every call. Conversion to host arrays is inside this custom autograd contract;
backward uses its independently checked physical Jacobian. Initial p/content
are fixed NumPy data, not trainable network state. No second derivatives,
episode-prior differentiation or GPU implementation is provided.
"""

from dataclasses import replace
import math

import numpy as np
import torch
from torch.autograd.function import once_differentiable

from qualification.hcsn_joint_dde.sensitivities import PARAMETERS, solve_partials


FIELDS = (
    "active",
    "upper",
    "refractory",
    "events",
    "discounted_events",
    "discounted_active_time",
    "discounted_remaining_phase",
)


class _PhysicalFlow(torch.autograd.Function):
    @staticmethod
    def forward(
        ctx, parameters, template, times, active, content, phase, options, solver
    ):
        if (
            parameters.device.type != "cpu"
            or parameters.dtype != torch.float64
            or parameters.shape != (5,)
            or not torch.isfinite(parameters).all()
        ):
            raise ValueError("five finite CPU FP64 physical parameters required")
        for initial in (active, content):
            if isinstance(initial, torch.Tensor):
                raise ValueError(
                    "initial laws must be fixed NumPy arrays; their gradients are unsupported"
                )
        boundary, drift, sigma, reset, discount = parameters.detach().numpy().tolist()
        if reset <= 0:
            raise ValueError("absolute reset must be positive")
        model = replace(
            template,
            spatial=replace(template.spatial, mu=drift, sigma=sigma),
            reset=math.log(reset) - boundary,
            discount=discount,
        )
        result = solver(
            model,
            times,
            active,
            content,
            phase,
            log_boundary=boundary,
            absolute_reset=reset,
            **options,
        )
        values, jacobian = [], []
        for row in result["rows"]:
            values.append(
                np.concatenate(
                    [np.asarray(row["primal"][field]).ravel() for field in FIELDS]
                )
            )
            jacobian.append(
                np.stack(
                    [
                        np.concatenate(
                            [
                                np.asarray(row["partials"][name][field]).ravel()
                                for field in FIELDS
                            ]
                        )
                        for name in PARAMETERS
                    ],
                    axis=-1,
                )
            )
        packed, derivative = np.stack(values), np.stack(jacobian)
        if not np.all(np.isfinite(packed)) or not np.all(np.isfinite(derivative)):
            raise ArithmeticError("nonfinite physical forward or Jacobian")
        ctx.save_for_backward(
            parameters, parameters.detach().clone(), torch.from_numpy(derivative)
        )
        return torch.from_numpy(packed)

    @staticmethod
    @once_differentiable
    def backward(ctx, gradient):
        parameters, original, jacobian = ctx.saved_tensors
        if not torch.equal(parameters, original):
            raise RuntimeError("physical parameters changed after forward")
        return (
            torch.einsum("tdp,td->p", jacobian, gradient),
            None,
            None,
            None,
            None,
            None,
            None,
            None,
        )


def physical_flow(parameters, template, times, active, content, phase=(), **options):
    """Differentiable only with respect to B/mu/sigma/Vr/q, fixed initial law."""
    return _PhysicalFlow.apply(
        parameters, template, times, active, content, phase, options, solve_partials
    )


def graded_physical_flow(
    parameters, template, times, active, content, phase=(), **options
):
    """Explicitly selected graded-v2 physical VJP; no uniform admission transfer."""
    from qualification.hcsn_joint_dde.graded_sensitivities import solve_graded_partials

    return _PhysicalFlow.apply(
        parameters,
        template,
        times,
        active,
        content,
        phase,
        options,
        solve_graded_partials,
    )
